struct Codec<SCSpecEventV0> {
  static constexpr std::uint64_t kMinSize = 20;
  static bool encode(const SCSpecEventV0&, Encoder&);
  static bool decode(SCSpecEventV0&, Decoder&);
  static bool gen(SCSpecEventV0&, XdrRng&, std::uint32_t);
  template <typename F>
  static void visit_fields(const SCSpecEventV0& v, F&& f) {
    f("doc", v.doc);
    f("lib", v.lib);
    f("name", v.name);
    f("prefixTopics", v.prefixTopics);
    f("params", v.params);
    f("dataFormat", v.dataFormat);
  }
};
